import { describe, expect, it } from 'vitest'
import { buildMockReport } from '../data/mock'
import { ipIndex } from '../lib/ipa'
import { FINANCIAL_CITATIONS } from '../components/FinancialTable'
import { fmtMoney, fmtMultiple, fmtRatio } from '../lib/format'

/**
 * Dataset conformance suite — binds the app's seed data to the IPA index
 * (generated by `npm run seed` from seed/src/content.mjs).
 *
 * Every claim the UI makes must trace verbatim to a block in the indexed
 * vault: document identity, page counts, section names, excerpt text, every
 * citation anchor, and every displayed financial figure.
 */

const report = buildMockReport()

function blocksOn(documentId: string, page: number) {
  const p = ipIndex.pages.find((x) => x.documentId === documentId && x.page === page)
  return p?.blocks ?? []
}

function textsOn(documentId: string, page: number): string[] {
  return blocksOn(documentId, page).map((b) => b.text)
}

function sectionCovers(documentId: string, name: string, page: number): boolean {
  return ipIndex.sections.some(
    (s) => s.documentId === documentId && s.name === name && s.start <= page && page <= s.end,
  )
}

describe('IPA index conformance', () => {
  it('indexes every document with matching page counts', () => {
    for (const d of report.documents) {
      const doc = ipIndex.documents.find((x) => x.id === d.id)
      expect(doc, `doc ${d.id} registered`).toBeTruthy()
      expect(doc!.pagesTotal).toBe(d.metadata.pagesTotal)
      expect(ipIndex.pages.filter((p) => p.documentId === d.id).length).toBe(d.metadata.pagesTotal)
    }
    expect(ipIndex.documents).toHaveLength(report.documents.length)
  })

  it('gives every indexed page at least one block', () => {
    for (const p of ipIndex.pages) {
      expect(p.blocks.length, `page ${p.documentId}#${p.page}`).toBeGreaterThan(0)
      for (const b of p.blocks) {
        expect(b.text.trim().length, `block text ${p.documentId}#${p.page}`).toBeGreaterThan(0)
      }
    }
  })

  it('resolves every Document excerpt to a verbatim block on its page', () => {
    for (const d of report.documents) {
      for (const e of d.excerpts) {
        const pageText = textsOn(d.id, e.page)
        expect(pageText.length, `excerpt page ${d.id}#${e.page} indexed`).toBeGreaterThan(0)
        const found = pageText.some((t) => t.includes(e.text))
        expect(found, `excerpt on ${d.id} p.${e.page} verbatim in a block`).toBe(true)
      }
    }
  })

  it('resolves every Document section heading to a section window containing that page', () => {
    for (const d of report.documents) {
      for (const s of d.sections) {
        expect(
          sectionCovers(d.id, s.heading, s.pageNumber),
          `section ${d.id} "${s.heading}" covers p.${s.pageNumber}`,
        ).toBe(true)
      }
    }
  })

  it('resolves every finding citation (document, page, section) and embeds its excerpt verbatim', () => {
    for (const f of report.findings) {
      for (const a of f.sources) {
        expect(blocksOn(a.documentId, a.page).length, `${f.id} page indexed`).toBeGreaterThan(0)
        if (a.section) {
          expect(sectionCovers(a.documentId, a.section, a.page), `${f.id} cite ${a.documentId} p.${a.page} "${a.section}"`).toBe(true)
        }
        if (a.excerpt) {
          const found = textsOn(a.documentId, a.page).some((t) => t.includes(a.excerpt ?? ''))
          expect(found, `${f.id} excerpt verbatim on ${a.documentId} p.${a.page}`).toBe(true)
        }
      }
    }
  })

  it('resolves every clause page against an indexed page (any section)', () => {
    for (const cl of report.clauses) {
      const pages = ipIndex.pages.filter((p) => p.documentId === cl.documentId && p.page === cl.page)
      expect(pages.length, `clause ${cl.id} page ${cl.documentId}#${cl.page}`).toBeGreaterThan(0)
    }
  })

  it('embeds every displayed financial figure verbatim on its cited page', () => {
    const f = report.financials
    const expects: Array<[string, number, string, string]> = [
      ['doc-annual-fy25', 26, 'revenue', fmtMoney(f.revenue!)],
      ['doc-annual-fy25', 28, 'operating costs', fmtMoney(f.operatingCosts!)],
      ['doc-annual-fy25', 26, 'net income', fmtMoney(f.netIncome!)],
      ['doc-audit-fy24', 9, 'EBITDA', fmtMoney(f.ebitda!)],
      ['doc-audit-fy24', 9, 'EBITDA margin', fmtRatio(f.ebitdaMargin!)],
      ['doc-annual-fy25', 33, 'cash', fmtMoney(f.cash!)],
      ['doc-loan', 4, 'debt', fmtMoney(f.debt!)],
      ['doc-loan', 4, 'debt/EBITDA', fmtMultiple(f.debtToEbitda!)],
      ['doc-market', 5, 'valuation', fmtMoney(f.valuation!)],
      ['doc-market', 5, 'valuation multiple', fmtMultiple(f.valuationMultiple!)],
    ]
    for (const [docId, page, label, value] of expects) {
      const found = textsOn(docId, page).some((t) => t.includes(value))
      expect(found, `${label} "${value}" on ${docId} p.${page}`).toBe(true)
    }
  })

  it('enables every citation used by the financial table (via FINANCIAL_CITATIONS)', () => {
    expect(FINANCIAL_CITATIONS.length).toBeGreaterThan(0)
    for (const a of FINANCIAL_CITATIONS) {
      expect(blocksOn(a.documentId, a.page).length, `financial cite ${a.documentId} p.${a.page}`).toBeGreaterThan(0)
      if (a.section) {
        expect(sectionCovers(a.documentId, a.section, a.page), `financial section ${a.section}`).toBe(true)
      }
    }
  })
})